import { Router } from 'express';
import multer from 'multer';
import fs from 'fs-extra';
import path from 'path';
import {
  createFolder,
  copyCompanyEntries,
  copyCompanyEntry,
  deleteEntry,
  deleteCompanyEntries,
  getCopyCompanyEntriesJob,
  getDeleteCompanyEntriesJob,
  getInfo,
  listEntries,
  moveEntry,
  uploadFile,
} from '../controllers/drive.controller.js';
import {
  getPdfMetadata,
  getPdfPageImage,
  getPdfPagePreviewGrid,
} from '../controllers/drive-pdf.controller.js';
import { config } from '../../config/environment.js';
import { requireTenant } from '../../middleware/tenant.middleware.js';
import { requireStorageQuota } from '../../middleware/quota.middleware.js';
import { uploadRateLimiter } from '../../middleware/company-rate-limiter.middleware.js';
import { createTusServer, tusMiddleware, getTusUploadInfo } from '../../services/tus-upload.service.js';

const router = Router();
const MAX_DRIVE_BYTES = 2 * 1024 * 1024 * 1024; // 2GB
let tempDir = path.join(config.storage.root, 'temp', 'uploads');
try {
  fs.ensureDirSync(tempDir);
} catch (error) {
  if (config.nodeEnv !== 'production') {
    const fallback = path.join(process.cwd(), 'data', 'storage', 'temp', 'uploads');
    fs.ensureDirSync(fallback);
    console.warn(
      `[drive] Failed to init temp dir at ${tempDir}. Using fallback: ${fallback}`
    );
    tempDir = fallback;
  } else {
    throw error;
  }
}

const upload = multer({
  storage: multer.diskStorage({
    destination: (_req, _file, cb) => cb(null, tempDir),
    filename: (_req, file, cb) => {
      const safeName = `${Date.now()}-${file.originalname}`;
      cb(null, safeName);
    },
  }),
  limits: { fileSize: MAX_DRIVE_BYTES },
});

const tusServer = createTusServer();
const tusCreateRateLimiter = (req, res, next) => {
  if (req.method === 'POST') {
    return uploadRateLimiter(req, res, next);
  }
  return next();
};

// Multi-tenant routes (require JWT authentication + quotas)
router.get('/upload-tus/:id/info', requireTenant, getTusUploadInfo);
router.all('/upload-tus', requireTenant, tusCreateRateLimiter, tusMiddleware(tusServer));
router.all('/upload-tus/*', requireTenant, tusCreateRateLimiter, tusMiddleware(tusServer));
router.get('/list', requireTenant, listEntries);
router.get('/info', requireTenant, getInfo);
router.post('/folders', requireTenant, createFolder);
router.post('/files', requireTenant, uploadRateLimiter, upload.single('file'), requireStorageQuota, uploadFile);
router.delete('/entry', requireTenant, deleteEntry);
router.patch('/move', requireTenant, moveEntry);
router.post('/admin/copy-company-entry', requireTenant, copyCompanyEntry);
router.post('/admin/copy-company-entries', requireTenant, copyCompanyEntries);
router.get('/admin/copy-company-entries/:jobId', requireTenant, getCopyCompanyEntriesJob);
router.post('/admin/delete-company-entries', requireTenant, deleteCompanyEntries);
router.get('/admin/delete-company-entries/:jobId', requireTenant, getDeleteCompanyEntriesJob);
router.get('/pdf/info', requireTenant, getPdfMetadata);
router.get('/pdf/page', requireTenant, getPdfPageImage);
router.get('/pdf/preview-grid', requireTenant, getPdfPagePreviewGrid);

export default router;
