const runWithConcurrency = async <T, R>(
  items: T[],
  limit: number,
  worker: (item: T) => Promise<R>
): Promise<Array<PromiseSettledResult<R>>> => {
  const results: Array<PromiseSettledResult<R>> = [];
  const pendingItems = [...items];
  const workers = Array.from(
    { length: Math.max(1, Math.min(limit, pendingItems.length || 1)) },
    async () => {
      while (pendingItems.length > 0) {
        const nextItem = pendingItems.shift();
        if (!nextItem) return;
        try {
          const value = await worker(nextItem);
          results.push({ status: 'fulfilled', value });
        } catch (error) {
          results.push({ status: 'rejected', reason: error });
        }
      }
    }
  );

  await Promise.all(workers);
  return results;
};

const buildSuccessStatusMessage = (
  input: PublicReceptionWorkflowInput,
  options: {
    resourceId: string;
    uploadedCount: number;
    failedCount: number;
    whatsappSent?: boolean;
  }
) => {
  const header =
    input.kind === 'measure'
      ? '✅ Registro de medida completado'
      : '✅ Registro de ingreso completado';
  const targetName =
    input.kind === 'measure'
      ? input.measureName
      : `${input.materialName} ${input.materialDescription}`.trim();

  const lines = [
    header,
    `Empresa: ${input.companyId}`,
    `Recurso: ${options.resourceId}`,
    `Detalle: ${targetName}`,
    `Transportista: ${input.kind === 'input' ? input.providerName : 'N/A'}`,
    `Ubicación: ${input.kind === 'input' ? input.locationName || 'Sin ubicación' : 'N/A'}`,
    `Cantera: ${input.kind === 'input' ? input.chancadora || 'N/A' : 'N/A'}`,
    `Dispositivo: ${'deviceName' in input ? input.deviceName || 'N/A' : 'N/A'}`,
    `Proveedor venta: ${input.kind === 'input' ? input.vendorProviderName || 'N/A' : 'N/A'}`,
    `Evidencias nuevas: ${options.uploadedCount}`,
  ];

  if (options.failedCount > 0) {
    lines.push(`Evidencias fallidas: ${options.failedCount}`);
  }

  if (input.kind === 'measure') {
    lines.push(`Medida: ${input.measureValue} ${input.unitLabel}`);
    lines.push(
      `WhatsApp: ${options.whatsappSent === false ? 'pendiente' : 'enviado'}`
    );
  }

  return lines.join('\n');
};

const buildFailureStatusMessage = (
  input: PublicReceptionWorkflowInput,
  error: unknown
) => {
  const message = error instanceof Error ? error.message : String(error);
  const targetName =
    input.kind === 'measure'
      ? input.measureName
      : `${input.materialName} ${input.materialDescription}`.trim();

  return [
    input.kind === 'measure'
      ? '❌ Registro de medida fallido'
      : '❌ Registro de ingreso fallido',
    `Empresa: ${input.companyId}`,
    `Detalle: ${targetName}`,
    `Transportista: ${input.kind === 'input' ? input.providerName : 'N/A'}`,
    `Ubicación: ${input.kind === 'input' ? input.locationName || 'Sin ubicación' : 'N/A'}`,
    `Cantera: ${input.kind === 'input' ? input.chancadora || 'N/A' : 'N/A'}`,
    `Dispositivo: ${'deviceName' in input ? input.deviceName || 'N/A' : 'N/A'}`,
    `Proveedor venta: ${input.kind === 'input' ? input.vendorProviderName || 'N/A' : 'N/A'}`,
    `Motivo: ${message}`,
  ].join('\n');
};

const processEvidenceUploads = async (params: {
  companyId: string;
  lilaPublicBaseUrl: string;
  resourceId: string;
  files: UploadedReceptionFile[];
  metadata: Record<string, unknown>;
  mediaType?: string;
}): Promise<{ uploadedCount: number; failedCount: number }> => {
  const { companyId, lilaPublicBaseUrl, resourceId, files, metadata, mediaType } = params;

  if (files.length === 0) {
    return { uploadedCount: 0, failedCount: 0 };
  }

  const settled = await runWithConcurrency(
    files,
    EVIDENCE_UPLOAD_CONCURRENCY,
    async (file) => {
      const uploadedFile = await storeFileInLilaDrive(
        companyId,
        lilaPublicBaseUrl,
        resourceId,
        file,
        mediaType
      );
      return createPortalMedia(
        companyId,
        createLilaMediaPayload(resourceId, uploadedFile, metadata, mediaType)
      );
    }
  );

  const uploadedCount = settled.filter(
    (result) => result.status === 'fulfilled'
  ).length;
  const failedCount = settled.length - uploadedCount;

  return { uploadedCount, failedCount };
};

const runInputReceptionWorkflow = async (input: PublicReceptionInput) => {
  const telegramChatId = input.telegramChatId;

  if (input.inputMode === 'standard') {
    const createdInput = await createPortalInput(input.companyId, {
      driver: input.driver,
      m3: input.m3 || 0,
      level: input.materialLevel,
      materialId: input.materialId,
      locationId: input.locationId,
      locationName: input.locationName,
      material: `${input.materialName} ${input.materialDescription}`.trim(),
      providerId: input.providerId,
      providerName: input.providerName,
      chancadora: input.chancadora,
      vendorProviderId: input.vendorProviderId,
      vendorProviderName: input.vendorProviderName,
      purchaseOrderId: input.purchaseOrderId,
      purchaseOrderNumber: input.purchaseOrderNumber,
      arriveDate: input.arriveDate || new Date().toLocaleString(),
      source: 'public-reception',
      inputMode: input.inputMode,
      deviceName: input.deviceName,
    });

    const uploadSummary = await processEvidenceUploads({
      companyId: input.companyId,
      lilaPublicBaseUrl: input.lilaPublicBaseUrl,
      resourceId: createdInput._id,
      files: input.files,
      metadata: {
        materialId: input.materialId,
      },
    });

    if (uploadSummary.uploadedCount === 0) {
      throw new Error('No se pudo registrar ninguna evidencia del ingreso');
    }

    await sendTelegramTextMessage(
      telegramChatId,
      buildSuccessStatusMessage(input, {
        resourceId: createdInput._id,
        uploadedCount: uploadSummary.uploadedCount,
        failedCount: uploadSummary.failedCount,
      })
    );

    return;
  }

  const [pendingInput] = await fetchPortalInputList(
    input.companyId,
    input.materialLevel
  );

  const activeInput =
    pendingInput ||
    (await createPortalInput(input.companyId, {
      driver: 'Recepción de Cisterna de PEN',
      m3: 0,
      level: input.materialLevel,
      materialId: input.materialId,
      locationId: input.locationId,
      locationName: input.locationName,
      material: `${input.materialName} ${input.materialDescription}`.trim(),
      providerId: input.providerId,
      providerName: input.providerName,
      vendorProviderId: input.vendorProviderId,
      vendorProviderName: input.vendorProviderName,
      purchaseOrderId: input.purchaseOrderId,
      purchaseOrderNumber: input.purchaseOrderNumber,
      arriveDate: input.arriveDate || new Date().toLocaleString(),
      source: 'public-reception',
      inputMode: input.inputMode,
      deviceName: input.deviceName,
    }));

  const uploadSummary = await processEvidenceUploads({
    companyId: input.companyId,
    lilaPublicBaseUrl: input.lilaPublicBaseUrl,
    resourceId: activeInput._id,
    files: input.files,
    metadata: {
      materialId: input.materialId,
    },
  });

  const existingMediaCount = await fetchPortalMediaCount(
    input.companyId,
    activeInput._id
  );
  if (existingMediaCount === 0) {
    throw new Error('No hay evidencias disponibles para completar el ingreso');
  }

  await updatePortalInput(input.companyId, activeInput._id, {
    ...activeInput,
    materialId: input.materialId,
    locationId: input.locationId || activeInput.locationId,
    locationName: input.locationName || activeInput.locationName,
    providerId: input.providerId,
    providerName: input.providerName,
    vendorProviderId: input.vendorProviderId,
    vendorProviderName: input.vendorProviderName,
    purchaseOrderId: input.purchaseOrderId,
    purchaseOrderNumber: input.purchaseOrderNumber,
    arriveDate: input.arriveDate || activeInput.arriveDate,
    status: 'Completed',
    source: 'public-reception',
    inputMode: input.inputMode,
    deviceName: input.deviceName,
  });

  await sendTelegramTextMessage(
    telegramChatId,
    buildSuccessStatusMessage(input, {
      resourceId: activeInput._id,
      uploadedCount: uploadSummary.uploadedCount,
      failedCount: uploadSummary.failedCount,
    })
  );
};

const runMeasureReceptionWorkflow = async (
  input: PublicMeasureReceptionInput
) => {
  const telegramChatId = input.telegramChatId;
  const [pendingMeasure] = await fetchPortalMeasureList(input.companyId, input.typeId);

  const activeMeasure =
    pendingMeasure ||
    (await createPortalMeasure(input.companyId, {
      name: input.measureName,
      measure: input.measureValue,
      date: new Date().toISOString(),
      status: 'Pending',
      typeId: input.typeId,
    }));

  const uploadSummary = await processEvidenceUploads({
    companyId: input.companyId,
    lilaPublicBaseUrl: input.lilaPublicBaseUrl,
    resourceId: activeMeasure._id,
    files: input.files,
    metadata: {
      typeId: input.typeId,
      measure: input.measureValue,
    },
  });

  const existingMediaCount = await fetchPortalMediaCount(
    input.companyId,
    activeMeasure._id
  );
  if (existingMediaCount === 0) {
    throw new Error('No hay evidencias disponibles para completar la medida');
  }

  await updatePortalMeasure(input.companyId, activeMeasure._id, {
    ...activeMeasure,
    name: input.measureName,
    measure: input.measureValue,
    typeId: input.typeId,
    status: 'Completed',
  });

  const whatsappSent =
    input.whatsappPhone && input.whatsappMessage
      ? await notifyPortalWhatsApp(
          input.companyId,
          input.whatsappPhone,
          input.whatsappMessage
        )
      : false;

  await sendTelegramTextMessage(
    telegramChatId,
    buildSuccessStatusMessage(input, {
      resourceId: activeMeasure._id,
      uploadedCount: uploadSummary.uploadedCount,
      failedCount: uploadSummary.failedCount,
      whatsappSent,
    })
  );
};

export const runPublicReceptionWorkflow = async (
  input: PublicReceptionWorkflowInput
) => {
  if (input.kind === 'measure') {
    await runMeasureReceptionWorkflow(input);
    return;
  }

  await runInputReceptionWorkflow(input);
};

const resolveCashFlowMovementResourceFields = (input: PublicCashFlowInput) => {
  if (input.resourceType === 'service') {
    return {
      projectId: undefined,
      orderId: undefined,
      resourceId: input.resourceId,
      resourceType: 'service',
      serviceManagementId: input.resourceId,
    };
  }

  if (input.resourceType === 'order') {
    return {
      orderId: input.resourceId,
      projectId: undefined,
      resourceId: input.resourceId,
      resourceType: 'order',
      serviceManagementId: undefined,
    };
  }

  return {
    orderId: undefined,
    projectId: input.resourceId,
    resourceId: input.resourceId,
    resourceType: 'project',
    serviceManagementId: undefined,
  };
};

const rollbackPortalFinancialMovement = async (params: {
  companyId: string;
  movementId?: string;
}) => {
  if (!params.movementId) {
    return;
  }

  await updatePortalFinancialMovement(params.companyId, params.movementId, {
    recordStatus: 'deleted',
  }).catch(() => undefined);
};

const runPublicCashFlowWorkflow = async (input: PublicCashFlowInput) => {
  let movementId: string | undefined;

  try {
    const sourceId = `public-cash-flow-${randomUUID()}`;
    const movement = await createPortalFinancialMovement(input.companyId, {
      sourceModule: 'manual',
      sourceId,
      movementType: input.movementType,
      ...resolveCashFlowMovementResourceFields(input),
      description: input.description,
      note: '',
      category: 'public-cash-flow',
      referenceNumber: '',
      paymentMethod: 'field',
      recordStatus: 'active',
      paymentStatus: 'not_applicable',
      baseCurrencyCode: 'PEN',
      currencyCode: 'PEN',
      exchangeRateToBase: 1,
      amountInCurrency: input.amountBase,
      amountBase: input.amountBase,
      referenceAmountBase: input.amountBase,
      date: new Date(input.date).toISOString(),
      attachmentMediaType: 'FINANCIAL_MOVEMENT',
      attachmentResourceIds: [sourceId],
      metadata: {
        deviceName: input.deviceName,
        resourceLabel: input.resourceLabel,
        source: 'public-cash-flow',
      },
    });

    movementId = movement._id;

    const uploadSummary = await processEvidenceUploads({
      companyId: input.companyId,
      lilaPublicBaseUrl: input.lilaPublicBaseUrl,
      files: input.files,
      mediaType: 'FINANCIAL_MOVEMENT',
      metadata: {
        movementId,
        resourceType: input.resourceType,
        source: 'public-cash-flow',
      },
      resourceId: sourceId,
    });

    if (uploadSummary.uploadedCount === 0) {
      throw new Error('No se pudo registrar ninguna evidencia del movimiento');
    }
  } catch (error) {
    await rollbackPortalFinancialMovement({
      companyId: input.companyId,
      movementId,
    });
    throw error;
  }
};

export const enqueuePublicReceptionWorkflow = (
  input: PublicReceptionWorkflowInput
) => {
  setImmediate(() => {
    void runPublicReceptionWorkflow(input).catch(async (error) => {
      const message = buildFailureStatusMessage(input, error);
      await sendTelegramTextMessage(input.telegramChatId, message);
      await sendTelegramAlert({
        dedupeKey: `public-reception:${input.companyId}:${input.kind}:${error instanceof Error ? error.message : String(error)}`,
        message,
      });
    }).finally(async () => {
      await cleanupUploadedFiles(input.files);
    });
  });

  return {
    accepted: true,
    kind: input.kind,
  };
};

export async function getCompanyLogin(req: Request, res: Response) {
  try {
    const slug = normalizeSlug(req.query.slug);

    if (!slug || !isValidSlug(slug)) {
      return res.status(400).json({
        ok: false,
        message: 'slug invalido',
      });
    }

    const cached = companyLoginCache.get(slug);
    if (cached && cached.expiresAt > Date.now()) {
      setPublicCacheHeaders(res);
      if (!cached.data) {
        return res.status(404).json({ ok: false, message: 'Empresa no encontrada' });
      }
      return res.status(200).json({ ok: true, data: cached.data });
    }

    const Company = await getCompanyModel();
    const company = await Company.findOne(
      { slug },
      {
        companyId: 1,
        slug: 1,
        name: 1,
        isActive: 1,
        'branding.logoLight': 1,
        'branding.logoDark': 1,
        'branding.favicon': 1,
      }
    ).lean();

    if (!company || company.isActive === false) {
      companyLoginCache.set(slug, {
        expiresAt: Date.now() + CACHE_TTL_MS,
        data: null,
      });
      setPublicCacheHeaders(res);
      return res.status(404).json({ ok: false, message: 'Empresa no encontrada' });
    }

    const data: CompanyLoginData = {
      companyId: company.companyId,
      slug: company.slug || slug,
      name: company.name,
      isActive: company.isActive !== false,
      branding: company.branding || undefined,
    };

    companyLoginCache.set(slug, {
      expiresAt: Date.now() + CACHE_TTL_MS,
      data,
    });

    setPublicCacheHeaders(res);
    return res.status(200).json({ ok: true, data });
  } catch (error) {
    console.error('[public] company-login error', error);
    return res.status(500).json({
      ok: false,
      message: 'Error consultando empresa',
    });
  }
}

export async function submitPublicReception(req: Request, res: Response) {
  const files = parseReceptionFiles(req);

  try {
    const input = parseReceptionInput(req);
    const accepted = enqueuePublicReceptionWorkflow(input);
    return res.status(202).json({
      success: true,
      data: accepted,
    });
  } catch (error) {
    await cleanupUploadedFiles(files);
    const message =
      error instanceof Error ? error.message : 'No se pudo iniciar el registro';
    const telegramChatId = trimValue(req.body?.telegramChatId);
    const companyId = trimValue(req.companyId);
    const alertMessage = [
      '❌ Registro de ingreso fallido',
      `Empresa: ${companyId || 'N/A'}`,
      `Dispositivo: ${trimValue(req.body?.deviceName) || 'N/A'}`,
      `Motivo: ${message}`,
    ].join('\n');

    if (telegramChatId) {
      await sendTelegramTextMessage(telegramChatId, alertMessage).catch(() => false);
    }
    await sendTelegramAlert({
      dedupeKey: `public-reception-start:${companyId}:${message}`,
      message: alertMessage,
    });

    return res.status(400).json({
      success: false,
      error: {
        message,
      },
    });
  }
}

export async function submitPublicFinancialMovement(req: Request, res: Response) {
  const files = parseReceptionFiles(req);

  try {
    const input = parseReceptionInput(req);
    if (input.kind !== 'cash-flow') {
      throw new Error('kind is invalid');
    }

    setImmediate(() => {
      void runPublicCashFlowWorkflow(input)
        .catch(async (error) => {
          const message = [
            '❌ Registro de flujo de caja fallido',
            `Empresa: ${input.companyId}`,
            `Recurso: ${input.resourceLabel}`,
            `Motivo: ${error instanceof Error ? error.message : String(error)}`,
          ].join('\n');
          await sendTelegramAlert({
            dedupeKey: `public-cash-flow:${input.companyId}:${input.resourceId}:${error instanceof Error ? error.message : String(error)}`,
            message,
          });
        })
        .finally(async () => {
          await cleanupUploadedFiles(input.files);
        });
    });

    return res.status(202).json({
      success: true,
      data: {
        accepted: true,
        kind: input.kind,
      },
    });
  } catch (error) {
    await cleanupUploadedFiles(files);
    const message =
      error instanceof Error ? error.message : 'No se pudo iniciar el registro';
    return res.status(400).json({
      success: false,
      error: {
        message,
      },
    });
  }
}
